import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("rate withdraw", () => {
  test("rate withdraw", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "30.00", "from": "2026-03-05"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00", "date": "2026-03-01"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("3.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("2.00");
    await expect(pg_uma.getByTestId("rate-current-A")).toHaveText("30.00");
    await expect(pg_uma.getByTestId("rate-current-B")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("rate-current-C")).toHaveText("n/a");
    await expect(pg_uma.getByTestId("rate-row-A-start").getByTestId("rate-pct")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("rate-row-A-start").getByTestId("rate-version")).toHaveText("2");
    await expect(pg_uma.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-pct")).toHaveText("30.00");
    await expect(pg_uma.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-version")).toHaveText("1");
    await expect(pg_uma.getByTestId("rate-row-B-start").getByTestId("rate-pct")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("rate-row-B-start").getByTestId("rate-version")).toHaveText("1");
    expect(await ui.withdrawRate(pg_uma, "A", "start")).toBe(false);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.withdrawRate(pg_vic, "A", "start")).toBe(true);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("3.00");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("1.00");
    await expect(pg_vic.getByTestId("rate-current-A")).toHaveText("30.00");
    await expect(pg_vic.getByTestId("rate-current-B")).toHaveText("5.00");
    await expect(pg_vic.getByTestId("rate-current-C")).toHaveText("n/a");
    await expect(pg_vic.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-pct")).toHaveText("30.00");
    await expect(pg_vic.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-version")).toHaveText("1");
    await expect(pg_vic.getByTestId("rate-row-B-start").getByTestId("rate-pct")).toHaveText("5.00");
    await expect(pg_vic.getByTestId("rate-row-B-start").getByTestId("rate-version")).toHaveText("1");
    await expect(pg_vic.getByTestId("rate-row-A-start").getByTestId("rate-pct")).toHaveText("10.00");
    await expect(pg_vic.getByTestId("rate-row-A-start").getByTestId("rate-version")).toHaveText("1");
    expect(await ui.withdrawRate(pg_vic, "A", "start")).toBe(true);
    expect(await ui.withdrawRate(pg_vic, "A", "2026-03-05")).toBe(true);
    expect(await ui.withdrawRate(pg_vic, "C", "start")).toBe(false);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("n/a");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("n/a");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("n/a");
    await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("20.00");
    await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("0");
    await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-settled-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-open-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("bulk-settle-batch")).toHaveText("");
    await expect(pg_vic.getByTestId("rollup-cut-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-aged-0-30")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-aged-31-60")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-aged-61")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rate-current-A")).toHaveText("n/a");
    await expect(pg_vic.getByTestId("rate-current-B")).toHaveText("5.00");
    await expect(pg_vic.getByTestId("rate-current-C")).toHaveText("n/a");
    await expect(pg_vic.getByTestId("rate-row-B-start").getByTestId("rate-pct")).toHaveText("5.00");
    await expect(pg_vic.getByTestId("rate-row-B-start").getByTestId("rate-version")).toHaveText("1");
    await ui.expectAudit(sheet, [
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=n/a overdue-total=0.00`,
      `ROLE_SET sheet=${sheet} by=uma user=vic role=steward`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=30.00 from=2026-03-05`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=5.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=2.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=10.00 due-total=2.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=5.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=20.00 due-total=5.00 overdue-total=0.00`,
      `RATE_WITHDRAWN sheet=${sheet} by=vic grade=A`,
      `ROLLUP sheet=${sheet} by=vic person=Ada claimed=20.00 due-total=4.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=vic claimed-total=20.00 due-total=4.00 overdue-total=0.00`,
      `RATE_WITHDRAWN sheet=${sheet} by=vic grade=A`,
      `ROLLUP sheet=${sheet} by=vic person=Ada claimed=20.00 due-total=3.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=vic claimed-total=20.00 due-total=3.00 overdue-total=0.00`,
      `RATE_WITHDRAWN sheet=${sheet} by=vic grade=A from=2026-03-05`,
      `ROLLUP sheet=${sheet} by=vic person=Ada claimed=20.00 due-total=n/a overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=vic claimed-total=20.00 due-total=0.00 overdue-total=0.00`
    ]);
  });
  return (await page.getByTestId('compare-line').allTextContents()).map((t) => t.trim());
}

/** Retire a grade: true once the screen shows it retired. */
export async function retireGrade(page: Page, grade: string): Promise<boolean> {
  const r = page.getByTestId(`grade-row-${grade}`);
  const done = async () => (await r.count()) > 0 && (await shown(r.getByTestId('grade-retired'))) === 'yes';
  const already = await done();
  try {
    await page.getByTestId('grade-retire-select').selectOption(grade, { timeout: 2000 });
  } catch {
    return false;
  }
  await page.getByTestId('grade-retire').click();
  return until(page, done, page.getByTestId('grade-error'), 'retire grade', already);
}

/** Add a grade: true once its row shows. */
export async function addGrade(page: Page, grade: string): Promise<boolean> {
  const r = page.getByTestId(`grade-row-${grade.trim()}`);
  const already = grade.trim() !== '' && (await r.count()) > 0;
  await page.getByTestId('grade-add-code').fill(grade);
  await page.getByTestId('grade-add').click();
  return until(page, async () => grade.trim() !== '' && (await r.count()) > 0, page.getByTestId('grade-error'), 'add grade', already);
}

/** Merge a grade into another: true once the screen shows the merge done. */
export async function mergeGrade(page: Page, from: string, into: string): Promise<boolean> {
  const cell = page.getByTestId('grade-merged');
  const was = await shown(cell);
  try {
    await page.getByTestId('grade-merge-from').selectOption(from, { timeout: 2000 });
    await page.getByTestId('grade-merge-into').selectOption(into, { timeout: 2000 });
  } catch {
    return false;
  }
  await page.getByTestId('grade-merge').click();
  await page.waitForTimeout(300);
  return until(page, async () => (await shown(cell)) !== '' && ((await shown(cell)) !== was || was === ''),
    page.getByTestId('grade-error'), 'merge grade');
}

/** Show the sheet as if today were a date (this user's screen only). */
export async function setPreview(page: Page, date: string): Promise<void> {
  await page.getByTestId('preview-date').fill(date);
  await page.getByTestId('preview-set').click();
  await expect(page.getByTestId('sheet-preview')).toHaveText(date, { timeout: LOAD_WAIT });
}

export async function clearPreview(page: Page): Promise<void> {
  await page.getByTestId('preview-clear').click();
  await expect(page.getByTestId('sheet-preview')).toHaveText('', { timeout: LOAD_WAIT });
}

/** Withdraw a rate's newest version: true once its row's version or presence changed. */
export async function withdrawRate(page: Page, grade: string, from: string): Promise<boolean> {
  const r = page.getByTestId(`rate-row-${grade}-${from}`);
  const was = (await r.count()) > 0 ? `${await shown(r.getByTestId('rate-pct'))}|${await shown(r.getByTestId('rate-version'))}` : '';
  if ((await r.count()) === 0) return false;
  await r.getByTestId('rate-withdraw').click();
  return until(page, async () => ((await r.count()) > 0 ? `${await shown(r.getByTestId('rate-pct'))}|${await shown(r.getByTestId('rate-version'))}` : '') !== was,
    page.getByTestId('rate-form-error'), 'withdraw rate');
}

/** The policy version lines, in order. */
export async function policyLines(page: Page): Promise<string[]> {
  await page.getByTestId('policy-show').click();
  await page.waitForTimeout(300);
  return (await page.getByTestId('policy-line').allTextContents()).map((t) => t.trim());
}

async function downloadOf(page: Page, testid: string): Promise<string> {
  const [download] = await Promise.all([page.waitForEvent('download'), page.getByTestId(testid).click()]);
  const path = await download.path();
  if (!path) throw new Error('export produced no file');
  return readFileSync(path, 'utf8');
}

export async function exportPeriods(page: Page): Promise<string> { return downloadOf(page, 'export-periods'); }
export async function exportTree(page: Page): Promise<string> { return downloadOf(page, 'export-tree'); }
export async function exportPolicy(page: Page): Promise<string> { return downloadOf(page, 'export-policy'); }
